    def backtrack(start, curr):
        if len(curr) == k:
            result.append(list(curr)); return
        remaining = k - len(curr)
        for i in range(start, len(nums) - remaining + 1):
            curr.append(nums[i])
            backtrack(i+1, curr)
            curr.pop()
    backtrack(0, [])
