def countArrangement(n):
    count = [0]
    used = [False] * (n+1)
    def backtrack(pos):
        if pos > n:
            count[0] += 1; return
        for num in range(1, n+1):
            if not used[num] and (num % pos == 0 or pos % num == 0):
                used[num] = True
                backtrack(pos+1)
                used[num] = False
    backtrack(1)
    return count[0]

def diffWaysToCompute(expression):
    results = []
    for i, c in enumerate(expression):
        if c in "+-*":
            left = diffWaysToCompute(expression[:i])
            right = diffWaysToCompute(expression[i+1:])
            for l in left:
                for r in right:
                    if c == '+': results.append(l+r)
                    elif c == '-': results.append(l-r)
                    else: results.append(l*r)
    if not results:
        results.append(int(expression))
    return results

def countTexts(pressedKeys):
    MOD = 10**9 + 7
    n = len(pressedKeys)
    dp = [0] * (n+1)
    dp[0] = 1
    for i in range(1, n+1):
        dp[i] = dp[i-1]
        if i >= 2 and pressedKeys[i-1] == pressedKeys[i-2]:
            dp[i] = (dp[i] + dp[i-2]) % MOD
            if i >= 3 and pressedKeys[i-1] == pressedKeys[i-3]:
                dp[i] = (dp[i] + dp[i-3]) % MOD
                if pressedKeys[i-1] in '79' and i >= 4 and pressedKeys[i-1] == pressedKeys[i-4]:
                    dp[i] = (dp[i] + dp[i-4]) % MOD
    return dp[n]

