def solveSudoku(board):
    def is_valid(r, c, num):
        ch = str(num)
        if ch in board[r]: return False
        if any(board[i][c] == ch for i in range(9)): return False
        br, bc = 3*(r//3), 3*(c//3)
        for i in range(br, br+3):
            for j in range(bc, bc+3):
                if board[i][j] == ch: return False
        return True
    def backtrack():
        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    for num in range(1, 10):
                        if is_valid(r, c, num):
                            board[r][c] = str(num)
                            if backtrack(): return True
                            board[r][c] = '.'
                    return False
        return True
    backtrack()

