def addOperators(num, target):
    result = []
    def backtrack(idx, path, value, last):
        if idx == len(num):
            if value == target: result.append(path)
            return
        for end in range(idx+1, len(num)+1):
            curr_str = num[idx:end]
            if len(curr_str) > 1 and curr_str[0] == '0': break  # no leading zeros
            curr = int(curr_str)
            if idx == 0:
                backtrack(end, curr_str, curr, curr)
            else:
                backtrack(end, path+'+'+curr_str, value+curr, curr)
                backtrack(end, path+'-'+curr_str, value-curr, -curr)
                backtrack(end, path+'*'+curr_str, value-last+last*curr, last*curr)
    backtrack(0, "", 0, 0)
    return result

