from collections import deque

def removeInvalidParentheses(s):
    def is_valid(t):
        count = 0
        for c in t:
            if c == '(': count += 1
            elif c == ')':
                count -= 1
                if count < 0: return False
        return count == 0

    visited = {s}
    queue = deque([s])
    result = []
    found = False
    while queue:
        level_size = len(queue)
        for _ in range(level_size):
            curr = queue.popleft()
            if is_valid(curr):
                result.append(curr)
                found = True
            if found: continue
            for i in range(len(curr)):
                if curr[i] not in '()': continue
                nxt = curr[:i] + curr[i+1:]
                if nxt not in visited:
                    visited.add(nxt)
                    queue.append(nxt)
        if found: break
    return result

