def findMinStep(board, hand):
    hand_count = {}
    for c in hand:
        hand_count[c] = hand_count.get(c, 0) + 1

    def remove_consecutive(b):
        # Remove groups of 3+ consecutive same-colored balls
        changed = True
        while changed:
            changed = False
            i = 0
            while i < len(b):
                j = i
                while j < len(b) and b[j] == b[i]: j += 1
                if j - i >= 3:
                    b = b[:i] + b[j:]
                    changed = True
                else:
                    i = j
        return b

    @lru_cache(maxsize=None)
    def dfs(board_str, hand_tuple):
        board_str = remove_consecutive(list(board_str))
        board_str = "".join(board_str)
        if not board_str: return 0
        hand_d = {}
        for c in hand_tuple: hand_d[c] = hand_d.get(c, 0) + 1
        best = float("inf")
        i = 0
        while i < len(board_str):
            j = i
            while j < len(board_str) and board_str[j] == board_str[i]: j += 1
            needed = 3 - (j - i)
            color = board_str[i]
            if hand_d.get(color, 0) >= needed:
                new_board = board_str[:i] + board_str[j:]
                new_hand = list(hand_tuple)
                for _ in range(needed): new_hand.remove(color)
                res = dfs(new_board, tuple(sorted(new_hand)))
                if res != -1:
                    best = min(best, needed + res)
            i = j
        return -1 if best == float("inf") else best

    return dfs(board, tuple(sorted(hand)))

