def mini_parser(s):
    stack = [[]]
    i = 0
    while i < len(s):
        if s[i] == '[':
            stack.append([])
            i += 1
        elif s[i] == ']':
            top = stack.pop()
            stack[-1].append(top)
            i += 1
        elif s[i] == ',':
            i += 1
        else:
            j = i
            while j < len(s) and s[j] not in ',[]':
                j += 1
            stack[-1].append(int(s[i:j]))
            i = j
    return stack[0][0] if len(stack[0]) == 1 else stack[0]

