def canWin(s):
    @lru_cache(maxsize=None)
    def can_win(state):
        state = list(state)
        for i in range(len(state) - 1):
            if state[i] == '+' and state[i+1] == '+':
                state[i] = state[i+1] = '-'
                if not can_win(tuple(state)):
                    state[i] = state[i+1] = '+'
                    return True
                state[i] = state[i+1] = '+'
        return False
    return can_win(tuple(s))

def isAdditiveNumber(num):
    n = len(num)
    def check(a, b, rest):
        s = str(a + b)
        if rest == s: return True
        if rest.startswith(s):
            return check(b, a + b, rest[len(s):])
        return False

    for i in range(1, n):
        for j in range(i + 1, n):
            a, b = num[:i], num[i:j]
            if (len(a) > 1 and a[0] == '0') or (len(b) > 1 and b[0] == '0'):
                continue
            if check(int(a), int(b), num[j:]):
                return True
    return False

