def assignBikes(workers, bikes):
    m, n = len(workers), len(bikes)
    INF = float('inf')
    dp = [INF] * (1 << n)
    dp[0] = 0

    def dist(w, b):
        return abs(w[0]-b[0]) + abs(w[1]-b[1])

    for mask in range(1 << n):
        worker_idx = bin(mask).count('1')
        if worker_idx >= m: continue
        if dp[mask] == INF: continue
        for bike_idx in range(n):
            if not (mask >> bike_idx & 1):
                new_mask = mask | (1 << bike_idx)
                new_cost = dp[mask] + dist(workers[worker_idx], bikes[bike_idx])
                dp[new_mask] = min(dp[new_mask], new_cost)

    return min(dp[mask] for mask in range(1 << n) if bin(mask).count('1') == m)

def makesquare(matchsticks):
    total = sum(matchsticks)
    if total % 4 != 0: return False
    side = total // 4
    matchsticks.sort(reverse=True)
    sides = [0] * 4

    def bt(idx):
        if idx == len(matchsticks):
            return sides[0] == sides[1] == sides[2] == side
        seen = set()
        for i in range(4):
            if sides[i] + matchsticks[idx] <= side and sides[i] not in seen:
                seen.add(sides[i])
                sides[i] += matchsticks[idx]
                if bt(idx + 1):
                    return True
                sides[i] -= matchsticks[idx]
        return False

    return bt(0)

def canPartitionKSubsets(nums, k):
    total = sum(nums)
    if total % k != 0: return False
    target = total // k
    nums.sort(reverse=True)
    if nums[0] > target: return False
    buckets = [0] * k

    def bt(idx):
        if idx == len(nums): return all(b == target for b in buckets)
        seen = set()
        for i in range(k):
            if buckets[i] + nums[idx] <= target and buckets[i] not in seen:
                seen.add(buckets[i])
                buckets[i] += nums[idx]
                if bt(idx + 1): return True
                buckets[i] -= nums[idx]
        return False

    return bt(0)

