def minAbbreviation(target, dictionary):
    n = len(target)
    if not dictionary: return str(n)

    def abbrev(word, mask):
        res, count = '', 0
        for i in range(n):
            if mask >> i & 1:
                if count: res += str(count)
                res += word[i]
                count = 0
            else:
                count += 1
        if count: res += str(count)
        return res

    def matches(abbr, word):
        i = j = 0
        while i < len(abbr) and j < len(word):
            if abbr[i].isdigit():
                num = 0
                while i < len(abbr) and abbr[i].isdigit():
                    num = num*10 + int(abbr[i]); i+=1
                j += num
            else:
                if abbr[i] != word[j]: return False
                i+=1; j+=1
        return i == len(abbr) and j == len(word)

    best = target
    for mask in range(1 << n):
        ab = abbrev(target, mask)
        if len(ab) < len(best):
            if not any(matches(ab, w) for w in dictionary if len(w)==n):
                best = ab
    return best

