def palindrome_partition_full(s):
    n = len(s)
    is_pal = [[False]*n for _ in range(n)]
    for i in range(n): is_pal[i][i] = True
    for i in range(n-1):
        is_pal[i][i+1] = (s[i] == s[i+1])
    for length in range(3, n+1):
        for i in range(n-length+1):
            j = i+length-1
            is_pal[i][j] = (s[i]==s[j] and is_pal[i+1][j-1])

    all_parts = []
    def bt(start, cur):
        if start == n:
            all_parts.append(list(cur))
            return
        for end in range(start, n):
            if is_pal[start][end]:
                cur.append(s[start:end+1])
                bt(end+1, cur)
                cur.pop()
    bt(0, [])

    min_cuts = min(len(p)-1 for p in all_parts)
    return all_parts, min_cuts

