def isMatch_wildcard(s, p):
    @lru_cache(maxsize=None)
    def dp(i, j):
        if j == len(p): return i == len(s)
        if p[j] == '*':
            return dp(i, j+1) or (i < len(s) and dp(i+1, j))
        first = i < len(s) and (p[j] == s[i] or p[j] == '?')
        return first and dp(i+1, j+1)
    return dp(0, 0)

from collections import Counter

def maxScoreWords(words, letters, score):
    letter_count = Counter(letters)
    best = [0]

    def bt(idx, available, cur_score):
        best[0] = max(best[0], cur_score)
        for i in range(idx, len(words)):
            word_cnt = Counter(words[i])
            if all(available[c] >= word_cnt[c] for c in word_cnt):
                for c in word_cnt:
                    available[c] -= word_cnt[c]
                word_score = sum(score[ord(c)-ord('a')] for c in words[i])
                bt(i+1, available, cur_score + word_score)
                for c in word_cnt:
                    available[c] += word_cnt[c]

    bt(0, letter_count, 0)
    return best[0]
